import bcrypt from "bcryptjs";

export type User = {
  id: string;
  email: string;
  name: string;
  createdAt: string;
  // Absent for users who only ever signed in via an OAuth provider (e.g. Google)
  // or magic link, and have never set a password.
  passwordHash?: string;
  // Bumped whenever the user asks to be signed out of all devices. Every JWT
  // embeds the version it was issued under; a mismatch means the token is stale.
  sessionVersion: number;
};

