import NextAuth from "next-auth";
import Credentials from "next-auth/providers/credentials";
import Google from "next-auth/providers/google";
import { findOrCreateUser, getUser, verifyPassword } from "@/lib/users";
import { consumeMagicLinkToken } from "@/lib/magic-link-tokens";

export const { handlers, signIn, signOut, auth } = NextAuth({
  providers: [
    Google({
      clientId: process.env.GOOGLE_CLIENT_ID,
      clientSecret: process.env.GOOGLE_CLIENT_SECRET,
    }),
    Credentials({
      id: "credentials",
      name: "Email and password",
      credentials: {
        email: { label: "Email", type: "email" },
        password: { label: "Password", type: "password" },
      },
      authorize: async (credentials) => {
        const email = credentials?.email;
        const password = credentials?.password;
        if (typeof email !== "string" || typeof password !== "string") return null;

        const user = await verifyPassword(email, password);
        if (!user) return null;

        return { id: user.id, email: user.email, name: user.name };
      },
    }),
    Credentials({
      // A second Credentials provider, not a real "magic link" email provider,
      // because Auth.js's built-in Email provider needs a database adapter to
      // store verification tokens — this app keeps its in-memory user store, so
      // /api/auth/magic-link issues its own single-use token (src/lib/magic-link-tokens.ts)
      // and hands it to this provider to exchange for a session.
      id: "magic-link",
      name: "Email link",
      credentials: {
        token: { label: "Token", type: "text" },
      },
      authorize: async (credentials) => {
        const token = credentials?.token;
        if (typeof token !== "string") return null;

        const email = consumeMagicLinkToken(token);
        if (!email) return null;

        const user = await findOrCreateUser({ email, name: email.split("@")[0] });
        return { id: user.id, email: user.email, name: user.name };
      },
    }),
  ],
  session: { strategy: "jwt" },
  pages: {
    signIn: "/signin",
  },
  callbacks: {
    async signIn({ user, account }) {
      // Provision (or link to) a local user record on first Google sign-in.
      if (account?.provider === "google" && user.email) {
        await findOrCreateUser({
          email: user.email,
          name: user.name ?? user.email,
        });
      }
      return true;
    },
    async jwt({ token, user }) {
      if (user) {
        // Fresh sign-in: stamp the token with the user's *current* session version.
        token.uid = user.id;
        const dbUser = await getUser(user.id);
        token.sessionVersion = dbUser?.sessionVersion ?? 1;
        return token;
      }

      if (typeof token.uid !== "string") return token;

      // Every other request: reject the token if "sign out of all devices" has
      // bumped the user's version since this token was issued.
      const dbUser = await getUser(token.uid);
      if (!dbUser || dbUser.sessionVersion !== token.sessionVersion) {
        return null;
      }
      return token;
    },
    async session({ session, token }) {
      if (typeof token.uid !== "string") {
        return { ...session, user: undefined };
      }
      session.user = { ...session.user, id: token.uid };
      return session;
    },
  },
});

