import { NextResponse } from "next/server";
import { createMagicLinkToken } from "@/lib/magic-link-tokens";
import { sendMagicLinkEmail } from "@/lib/mailer";

export async function POST(req: Request) {
  const body = await req.json().catch(() => null);
  const email = typeof body?.email === "string" ? body.email.trim().toLowerCase() : "";

  if (!email || !email.includes("@")) {
    return NextResponse.json({ error: "Enter a valid email address." }, { status: 400 });
  }

  const token = createMagicLinkToken(email);
  const origin = new URL(req.url).origin;
  const url = `${origin}/api/auth/magic-link/verify?token=${token}`;

  await sendMagicLinkEmail(email, url);

  // Always respond the same way regardless of whether this email already has an
  // account — magic-link sign-in provisions a new user on first use, and this
  // avoids leaking which emails are registered.
  return NextResponse.json({ ok: true });
}

