import { useState } from "react";

export function SignOutAllButton() {
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  async function handleClick() {
    setError(null);
    setLoading(true);

    const res = await fetch("/api/account/sign-out-all", { method: "POST" });

    if (!res.ok) {
      setLoading(false);
      setError("Something went wrong.");
      return;
    }

    window.location.href = "/signin";
  }

  return (
    <div className="space-y-2">
      {error && <p className="text-sm text-red-600 dark:text-red-400">{error}</p>}
      <button
        type="button"
        onClick={handleClick}
        disabled={loading}
        className="flex h-10 items-center justify-center rounded-full border border-black/[.08] px-5 text-sm font-medium transition-colors hover:bg-black/[.04] disabled:opacity-60 dark:border-white/[.145] dark:hover:bg-[#1a1a1a]"
      >
        {loading ? "Signing out…" : "Sign out of all devices"}
      </button>
    </div>
  );
}

