"use client";

import { useState, type FormEvent } from "react";

export function DeleteAccountForm({ hasPassword }: { hasPassword: boolean }) {
  const [password, setPassword] = useState("");
  const [confirming, setConfirming] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [loading, setLoading] = useState(false);

  async function handleSubmit(e: FormEvent) {
    e.preventDefault();
    setError(null);
    setLoading(true);

    const res = await fetch("/api/account/delete", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ password }),
    });

    if (!res.ok) {
      const data = await res.json().catch(() => ({}));
      setLoading(false);
      setError(data.error ?? "Something went wrong.");
      return;
    }

    window.location.href = "/";
  }

  if (!confirming) {
    return (
      <button
        type="button"
        onClick={() => setConfirming(true)}
        className="flex h-10 items-center justify-center rounded-full border border-red-600/40 px-5 text-sm font-medium text-red-700 transition-colors hover:bg-red-600/10 dark:text-red-400"
      >
        Delete account
      </button>
    );
  }

  return (
    <form onSubmit={handleSubmit} className="space-y-3">
      {hasPassword && (
        <div className="space-y-1">
          <label htmlFor="deletePassword" className="text-sm font-medium">
            Confirm your password
          </label>
          <input
            id="deletePassword"
            type="password"
            required
            value={password}
            onChange={(e) => setPassword(e.target.value)}
            className="w-full rounded-md border border-black/[.08] bg-transparent px-3 py-2 text-sm outline-none focus:border-red-400 dark:border-white/[.145]"
          />
        </div>
      )}
      <p className="text-sm text-red-700 dark:text-red-400">
        This permanently deletes your account. This can&apos;t be undone.
      </p>

      {error && <p className="text-sm text-red-600 dark:text-red-400">{error}</p>}

      <div className="flex gap-2">
        <button
          type="submit"
          disabled={loading}
          className="flex h-10 items-center justify-center rounded-full bg-red-700 px-5 text-sm font-medium text-white transition-colors hover:bg-red-800 disabled:opacity-60"
        >
          {loading ? "Deleting…" : "Yes, delete my account"}
        </button>
        <button
          type="button"
          onClick={() => setConfirming(false)}
          className="flex h-10 items-center justify-center rounded-full border border-black/[.08] px-5 text-sm font-medium dark:border-white/[.145]"
        >
          Cancel
        </button>
      </div>
    </form>
  );
}

